import Foundation

/// The web's own interface catalogs (src/i18n: en + 11 locales, generated by
/// scripts/native-ui-strings-vectors.ts) with ports of its t(), tp() and fmtNumber().
public struct ChapterStrings: Sendable {
    public let locales: [String]
    let catalogs: [String: [String: String]]

    public static let bundled: ChapterStrings = {
        guard let url = Bundle.module.url(forResource: "ui-messages", withExtension: "json"), let data = try? Data(contentsOf: url),
              let decoded = try? JSONDecoder().decode(Decoded.self, from: data) else { return ChapterStrings(locales: ["en"], catalogs: ["en": [:]]) }
        return ChapterStrings(locales: decoded.locales, catalogs: decoded.catalogs)
    }()
    struct Decoded: Decodable { let locales: [String]; let catalogs: [String: [String: String]] }
    init(locales: [String], catalogs: [String: [String: String]]) { self.locales = locales; self.catalogs = catalogs }

    public func resolvedLocale(_ id: String) -> String { locales.contains(id) ? id : "en" }
    func lookup(_ key: String, locale: String) -> String? { catalogs[resolvedLocale(locale)]?[key] ?? catalogs["en"]?[key] }

    /// Web t(): catalog, then English, then the key; `{name}` (\w+) filled from params, unknown names kept.
    public func t(_ key: String, _ params: [String: String] = [:], locale: String) -> String {
        Self.interpolate(lookup(key, locale: locale) ?? key, params)
    }
    /// Web tp(): `base#<CLDR category>` when present, else `base#other`; `{count}` is String(count).
    public func tp(_ base: String, count: Double, _ params: [String: String] = [:], locale: String) -> String {
        let exact = base + "#" + Self.pluralCategory(count, locale: resolvedLocale(locale))
        let key = lookup(exact, locale: locale) != nil ? exact : base + "#other"
        var all = params; all["count"] = Self.jsString(count)
        return t(key, all, locale: locale)
    }

    static func interpolate(_ template: String, _ params: [String: String]) -> String {
        guard !params.isEmpty, template.contains("{") else { return template }
        let chars = Array(template.unicodeScalars); var out = String.UnicodeScalarView(); var i = 0
        func word(_ c: Unicode.Scalar) -> Bool { (c >= "a" && c <= "z") || (c >= "A" && c <= "Z") || (c >= "0" && c <= "9") || c == "_" }
        while i < chars.count {
            if chars[i] == "{" {
                var j = i + 1
                while j < chars.count, word(chars[j]) { j += 1 }
                if j > i + 1, j < chars.count, chars[j] == "}" {
                    let name = String(String.UnicodeScalarView(chars[(i + 1)..<j]))
                    if let value = params[name] { out.append(contentsOf: value.unicodeScalars) } else { out.append(contentsOf: chars[i...j]) }
                    i = j + 1; continue
                }
            }
            out.append(chars[i]); i += 1
        }
        return String(out)
    }

    /// JavaScript String(number) for the finite values the app passes (integers and short decimals).
    static func jsString(_ n: Double) -> String {
        if n == n.rounded(), abs(n) < 1e21 { return String(Int64(n)) }
        return "\(n)"
    }

    /// CLDR cardinal plural rules (as Intl.PluralRules) for the web's 12 locales.
    public static func pluralCategory(_ n: Double, locale: String) -> String {
        let text = jsString(abs(n)); let parts = text.split(separator: ".", maxSplits: 1)
        let i = Int64(parts.first ?? "0") ?? 0, v = parts.count > 1 ? parts[1].count : 0
        let integral = v == 0
        switch locale {
        case "en", "de", "nl", "fi": return i == 1 && integral ? "one" : "other"
        case "it": if i == 1 && integral { return "one" }; return integral && i != 0 && i % 1_000_000 == 0 ? "many" : "other"
        case "es": if abs(n) == 1 { return "one" }; return integral && i != 0 && i % 1_000_000 == 0 ? "many" : "other"
        case "fr": if i == 0 || i == 1 { return "one" }; return integral && i != 0 && i % 1_000_000 == 0 ? "many" : "other"
        case "hi": return i == 0 || abs(n) == 1 ? "one" : "other"
        case "ar":
            guard integral else { return "other" }
            let m = i % 100
            if i == 0 { return "zero" }; if i == 1 { return "one" }; if i == 2 { return "two" }
            if (3...10).contains(m) { return "few" }; if (11...99).contains(m) { return "many" }; return "other"
        default: return "other"
        }
    }

    /// Web fmtNumber(): Intl.NumberFormat(locale) defaults (0–3 fraction digits, half-expand
    /// on the shortest decimal form, Latin digits as the web's locales use) or fixed fraction
    /// digits. Rounding is done here so no platform formatter's rounding mode is relied on.
    public static func formatNumber(_ n: Double, locale: String, fractionDigits: Int? = nil) -> String {
        guard n.isFinite else { return jsString(n) }
        let minimum = fractionDigits ?? 0, maximum = fractionDigits ?? 3
        var value = Decimal(string: "\(abs(n))", locale: Locale(identifier: "en_US_POSIX")) ?? Decimal(abs(n)), rounded = Decimal()
        NSDecimalRound(&rounded, &value, maximum, .plain)
        let plain = NSDecimalNumber(decimal: rounded).stringValue // "1234.5" (POSIX, no exponent for these ranges)
        let parts = plain.split(separator: ".", maxSplits: 1)
        var fraction = parts.count > 1 ? String(parts[1]) : ""
        while fraction.count > minimum, fraction.hasSuffix("0") { fraction.removeLast() }
        while fraction.count < minimum { fraction += "0" }
        // CLDR decimal symbols and grouping for the web's 12 locales (Intl output; see vectors),
        // applied here so Apple and Linux Foundation formatter differences cannot leak in.
        let symbols: (group: String, decimal: String, minimumGrouping: Int, secondary: Int) = switch locale {
        case "de", "nl": (".", ",", 1, 3)
        case "es", "it": (".", ",", 2, 3)
        case "fr": ("\u{202F}", ",", 1, 3)
        case "fi": ("\u{00A0}", ",", 1, 3)
        case "hi": (",", ".", 1, 2)
        default: (",", ".", 1, 3)
        }
        var digits = Array(String(parts.first ?? "0")), groups: [String] = []
        if digits.count >= 3 + symbols.minimumGrouping {
            groups.insert(String(digits.suffix(3)), at: 0); digits.removeLast(3)
            while digits.count > symbols.secondary { groups.insert(String(digits.suffix(symbols.secondary)), at: 0); digits.removeLast(symbols.secondary) }
        }
        if !digits.isEmpty { groups.insert(String(digits), at: 0) }
        let integer = groups.joined(separator: symbols.group)
        let sign = n < 0 && rounded != 0 ? "-" : ""
        return sign + integer + (fraction.isEmpty ? "" : symbols.decimal + fraction)
    }
}

public struct GeoPoint: Equatable, Sendable { public let lat: Double; public let lng: Double; public let label: String }

/// Web editor/location.tsx nodeData(): `from` and `map` required, zoom defaults to 13.
public struct LocationCardData: Equatable {
    public let from: GeoPoint
    public let to: GeoPoint?
    public let zoom: Double
    public let map: VaultMedia
    public let photo: VaultMedia?
    public let mapWidth: Double?, mapHeight: Double?

    public init?(_ attrs: JSONValue) {
        func point(_ raw: JSONValue) -> GeoPoint? {
            guard let lat = raw["lat"].number, let lng = raw["lng"].number else { return nil }
            return GeoPoint(lat: lat, lng: lng, label: raw["label"].string ?? "")
        }
        func media(_ raw: JSONValue) -> VaultMedia? {
            guard let id = raw["id"].string, !id.isEmpty else { return nil }
            let size = raw["bytes"].number ?? 0
            let bytes = size.isFinite ? Int(exactly: size.rounded(.towardZero)) ?? 0 : 0
            let name = raw["name"].string ?? ""
            return VaultMedia(id: id, kind: "image", mime: raw["mime"].string ?? "image/jpeg", name: name, bytes: bytes)
        }
        guard let from = point(attrs["from"]), let map = media(attrs["map"]) else { return nil }
        self.from = from; self.to = point(attrs["to"]); self.zoom = attrs["zoom"].number ?? 13
        self.map = map; self.photo = media(attrs["photo"])
        self.mapWidth = attrs["map"]["width"].number; self.mapHeight = attrs["map"]["height"].number
    }
    /// Web aspect ratio: map width/height when both present (non-zero), else 600/340.
    public var aspectRatio: Double {
        if let w = mapWidth, let h = mapHeight, w != 0, h != 0 { return w / h }
        return 600.0 / 340.0
    }
    public var distanceKm: Double? { to.map { Self.haversineKm(from, $0) } }

    public static func haversineKm(_ a: GeoPoint, _ b: GeoPoint) -> Double {
        let r = 6371.0, rad = { (d: Double) in d * Double.pi / 180 }
        let dLat = rad(b.lat - a.lat), dLng = rad(b.lng - a.lng)
        let h = pow(sin(dLat / 2), 2) + cos(rad(a.lat)) * cos(rad(b.lat)) * pow(sin(dLng / 2), 2)
        return 2 * r * asin(min(1, h.squareRoot()))
    }
    /// Web fmtDistance(): metres below 1 km, one decimal below 10 km, whole km after.
    public static func formatDistance(_ km: Double, locale: String, strings: ChapterStrings = .bundled) -> String {
        func jsRound(_ x: Double) -> Double { (x + 0.5).rounded(.down) }
        if km < 1 { return strings.t("editorx.location.distanceM", ["n": ChapterStrings.formatNumber(jsRound(km * 1000), locale: locale)], locale: locale) }
        if km < 10 { return strings.t("editorx.location.distanceKm", ["n": ChapterStrings.formatNumber(km, locale: locale, fractionDigits: 1)], locale: locale) }
        return strings.t("editorx.location.distanceKm", ["n": ChapterStrings.formatNumber(jsRound(km), locale: locale)], locale: locale)
    }
}
